    n_colors = random.choice((3, 4, 5))
    base = random.choice(LEGEND_SHAPES[n_colors])
    cells = list(_transform_cells(base))

    palette = [color for color in range(10) if color != GREY]
    colors = random.sample(palette, n_colors + 1)
